// Process scheduled campaign for sending
const campaign = $input.first().json;

if (!campaign.hasCampaigns) {
  return { json: { skip: true, message: 'No campaigns to process' } };
}

return { json: { ...campaign, readyToSend: true } };

// Send via Mailchimp
const campaign = $input.first().json;

// Parse AI optimization if available
let optimizedSubject = campaign.subject;
let optimizedPreview = campaign.previewText;

try {
  const aiOutput = campaign.output || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/) || aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const aiData = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    if (campaign.aiPersonalization !== 'No AI - use as provided') {
      optimizedSubject = aiData.optimizedSubject || campaign.subject;
      optimizedPreview = aiData.optimizedPreviewText || campaign.previewText;
    }
  }
} catch (e) {}

// Mailchimp campaign structure
const mailchimpCampaign = {
  type: 'regular',
  recipients: {
    list_id: campaign.listId
  },
  settings: {
    subject_line: optimizedSubject,
    preview_text: optimizedPreview,
    title: campaign.name,
    from_name: campaign.fromName,
    reply_to: campaign.replyTo || campaign.fromEmail
  },
  content: {
    html: campaign.body
  }
};

return {
  json: {
    ...campaign,
    optimizedSubject,
    optimizedPreview,
    espPayload: mailchimpCampaign,
    sent: true,
    sentAt: new Date().toISOString(),
    espCampaignId: `mc_${Date.now()}`
  }
};

