// Schedule follow-up performance check
const campaign = $input.first().json;

// In production, this would create a scheduled task
// to check campaign performance after 24-48 hours

const followUp = {
  campaignId: campaign.id,
  espCampaignId: campaign.espCampaignId,
  esp: campaign.esp,
  checkAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // 24 hours later
  metricsToCheck: ['opens', 'clicks', 'bounces', 'unsubscribes']
};

return {
  json: {
    ...campaign,
    followUpScheduled: true,
    followUp
  }
};
